import{_ as d,C as c,o as t,c as i,an as o,b as s,w as a,a as l,E as n,ao as m}from"./chunks/framework.BdQmZfLw.js";const v=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"dev/architecture.md","filePath":"dev/architecture.md","lastUpdated":null}'),p={name:"dev/architecture.md"};function h(g,e,u,f,y,b){const r=c("Mermaid");return t(),i("div",null,[e[1]||(e[1]=o('<h1 id="Architecture-Overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#Architecture-Overview" aria-label="Permalink to &quot;Architecture Overview {#Architecture-Overview}&quot;">​</a></h1><p>This page maps the source tree and the core design decisions a developer needs before touching the code. For extension recipes (adding an energy term) see <a href="./@ref">Contributing</a>; for the parameter-representation system see <a href="./params">Parameter System</a>.</p><h2 id="Source-tree" tabindex="-1">Source tree <a class="header-anchor" href="#Source-tree" aria-label="Permalink to &quot;Source tree {#Source-tree}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">path</th><th style="text-align:left;">contents</th></tr></thead><tbody><tr><td style="text-align:left;"><code>src/MicroMagnetic.jl</code></td><td style="text-align:left;">module definition, global state (precision/backend/groupsize), <code>set_precision</code> / <code>set_backend</code> / <code>set_verbose</code></td></tr><tr><td style="text-align:left;"><code>src/head.jl</code></td><td style="text-align:left;"><code>AbstractSim</code> hierarchy, energy-term and driver abstract types, type aliases (<code>NumberOrArrayOrFunction</code>, ...)</td></tr><tr><td style="text-align:left;"><code>src/fill.jl</code></td><td style="text-align:left;"><code>Fill{T,N}</code> — O(1) storage for uniform parameters (see <a href="./params">Parameter System</a>)</td></tr><tr><td style="text-align:left;"><code>src/params.jl</code></td><td style="text-align:left;"><code>make_param</code> / <code>make_vector_param</code> (the single materialisation point), <code>set_region</code>, <code>region_map</code></td></tr><tr><td style="text-align:left;"><code>src/driver.jl</code></td><td style="text-align:left;"><code>SD{T}</code> / <code>LLG{T}</code> / <code>InertialLLG{T}</code> drivers, <code>create_driver</code>, <code>set_driver</code></td></tr><tr><td style="text-align:left;"><code>src/sim.jl</code></td><td style="text-align:left;"><code>Sim</code> factory, <code>relax</code>, <code>run_sim</code>, <code>run_until</code>, <code>hysteresis</code>, saver plumbing</td></tr><tr><td style="text-align:left;"><code>src/micro/</code></td><td style="text-align:left;">finite-difference micromagnetics: mesh, energy terms (<code>add_field.jl</code>), kernels, demag (incl. PBC solvers, stencil partition)</td></tr><tr><td style="text-align:left;"><code>src/atomistic/</code></td><td style="text-align:left;">lattice spin dynamics: meshes (<code>CubicMesh</code>, <code>TriangularMesh</code>, <code>CylindricalTubeMesh</code>), energy terms, kernels</td></tr><tr><td style="text-align:left;"><code>src/llg/</code></td><td style="text-align:left;">LLG right-hand sides: standard, Cayley form, inertial LLG</td></tr><tr><td style="text-align:left;"><code>src/integrator/</code></td><td style="text-align:left;">adaptive RK family (DOPRI54, ...), Cayley integrators, Heun, GPSM</td></tr><tr><td style="text-align:left;"><code>src/mc/</code></td><td style="text-align:left;">Monte Carlo (atomistic): <code>MonteCarlo</code> sim type, sweeps, observables</td></tr><tr><td style="text-align:left;"><code>src/fem/</code></td><td style="text-align:left;">finite-element micromagnetics (FEMesh, <code>MicroSimFE</code>)</td></tr><tr><td style="text-align:left;"><code>src/eigen/</code></td><td style="text-align:left;">eigenmode analysis: <code>build_matrix</code>, <code>LLGJacOperator</code>, symbolic mode</td></tr><tr><td style="text-align:left;"><code>src/transition/</code></td><td style="text-align:left;">GNEB, saddle-point search, minimum-mode method</td></tr><tr><td style="text-align:left;"><code>src/neb/</code></td><td style="text-align:left;">classical NEB</td></tr><tr><td style="text-align:left;"><code>src/tools/</code></td><td style="text-align:left;">LTEM phase, topology (skyrmion number, guiding center)</td></tr><tr><td style="text-align:left;"><code>src/csg.jl</code></td><td style="text-align:left;">constructive solid geometry shapes and boolean operators</td></tr><tr><td style="text-align:left;"><code>src/ovf2.jl</code> / <code>src/vtk.jl</code> / <code>src/fileio.jl</code></td><td style="text-align:left;">OVF, VTK and table I/O</td></tr><tr><td style="text-align:left;"><code>src/server.jl</code></td><td style="text-align:left;">WebSocket server behind <code>gui()</code></td></tr><tr><td style="text-align:left;"><code>ext/CUDAExt.jl</code> etc.</td><td style="text-align:left;">backend package extensions (CUDA, AMDGPU, oneAPI, Metal)</td></tr></tbody></table><h2 id="Simulation-type-hierarchy" tabindex="-1">Simulation type hierarchy <a class="header-anchor" href="#Simulation-type-hierarchy" aria-label="Permalink to &quot;Simulation type hierarchy {#Simulation-type-hierarchy}&quot;">​</a></h2>',5)),(t(),s(m,null,{default:a(()=>[n(r,{id:"mermaid-186",class:"mermaid",graph:"graph%20TD%0A%20%20%20AbstractSim%20--%3E%20MicroSim%0A%20%20%20AbstractSim%20--%3E%20MicroSimFE%0A%20%20%20AbstractSim%20--%3E%20AtomisticSim%0A%20%20%20AbstractSim%20--%3E%20NEB%0A%20%20%20AbstractSim%20--%3E%20MonteCarlo%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>A <code>Sim</code> object owns four central buffers, all of length <code>3N</code> (N = number of cells), interleaved as <code>[m₁ₓ, m₁ᵧ, m₁_z, m₂ₓ, ...]</code>:</p><ul><li><p><code>sim.spin</code> — the magnetization state,</p></li><li><p><code>sim.field</code> — the accumulated effective field,</p></li><li><p><code>sim.prespin</code> — scratch copy used by <code>relax</code>,</p></li><li><p>per-interaction <code>interaction.field</code> buffers.</p></li></ul><p>Cell <code>(i, j, k)</code> maps to the flat index <code>id = (k-1)*nx*ny + (j-1)*nx + i</code>, so the three components of the field at that cell are <code>field[3id-2 : 3id]</code>. To scan neighbors, use the precomputed <code>mesh.ngbs</code> table (6 neighbors per cell, <code>id &gt; 0</code> means the neighbor exists; periodic axes wrap) rather than recomputing indices — <code>index(i,j,k,...)</code> for open meshes and <code>indexpbc(...)</code> for periodic ones are the canonical index helpers.</p><h2 id="Energy-terms" tabindex="-1">Energy terms <a class="header-anchor" href="#Energy-terms" aria-label="Permalink to &quot;Energy terms {#Energy-terms}&quot;">​</a></h2><p>Every term is a subtype of <code>MicroEnergy</code> (atomistic: <code>AtomisticEnergy</code>-style kernels) stored in <code>sim.interactions::Array{MicroEnergy}</code>. The effective field evaluation loops over interactions, computes each term&#39;s field into its private buffer, then accumulates into <code>sim.field</code>. Each term also exposes its energy density for the saver (<code>E_exch</code>, <code>E_demag</code>, ... columns).</p><p>Since the Fill refactor, a term&#39;s parameters are <strong>arrays, never scalars</strong>: a uniform parameter is stored as a <code>Fill</code> (O(1)) and a spatial one as a dense array, so <code>Exchange</code> / <code>DMI</code> / <code>LLG</code> have no <code>Spatial*</code> twin types anymore. See <a href="./params">Parameter System</a> for the full contract.</p><h2 id="Drivers" tabindex="-1">Drivers <a class="header-anchor" href="#Drivers" aria-label="Permalink to &quot;Drivers {#Drivers}&quot;">​</a></h2><p><code>None</code>, <code>SD</code> (energy minimisation), <code>LLG</code> (Gilbert dynamics; also serves the stochastic LLG via <code>add_thermal_noise</code>) and <code>InertialLLG</code>. Drivers are parameterised by the element type <code>T</code> that is frozen in at <code>Sim</code> construction; <code>set_driver</code> is the only supported way to switch (see <a href="./drivers">Driver Internals</a>).</p><h2 id="Global-state:-precision,-backend,-group-size" tabindex="-1">Global state: precision, backend, group size <a class="header-anchor" href="#Global-state:-precision,-backend,-group-size" aria-label="Permalink to &quot;Global state: precision, backend, group size {#Global-state:-precision,-backend,-group-size}&quot;">​</a></h2><p>Three module-level <code>Ref</code>s exist (<code>Float</code>, <code>default_backend</code>, <code>groupsize</code>), but their role is deliberately narrow — <strong>constructor-time defaults</strong>:</p><ul><li><p><code>set_precision(T)</code> answers &quot;what element type will <em>future</em> allocations use&quot;. A <code>Sim</code> freezes <code>T</code> into its type parameter; existing simulations are never touched (a warning fires if sims already exist). Legal values: <code>Float64</code>, <code>Float32</code>, <code>AbstractFloat</code> (symbolic mode, eigen workflow only).</p></li><li><p><code>set_backend(s)</code> answers &quot;where will <em>future</em> allocations live&quot;. Kernels never read this global at run time — the invariant is <strong>the backend is derived from the data</strong>: <code>KernelAbstractions.get_backend(sim.spin)</code> (or the buffer the kernel actually touches). Host-side temporaries must not be used to derive a kernel backend; that compiles a CPU kernel against device arrays and fails with scalar-indexing errors.</p></li><li><p><code>set_groupsize(n)</code> is a pure performance knob for kernel launches.</p></li></ul><p>Remaining legal read sites of the globals are allocation points only (<code>create_zeros</code>, <code>make_param</code> host materialisation, <code>FDMesh</code> construction, the setters themselves). When adding code, follow the same rule.</p><h2 id="Backend-package-extensions" tabindex="-1">Backend package extensions <a class="header-anchor" href="#Backend-package-extensions" aria-label="Permalink to &quot;Backend package extensions {#Backend-package-extensions}&quot;">​</a></h2><p>The package itself only depends on KernelAbstractions. GPU support lives in package extensions (<code>ext/CUDAExt.jl</code>, ...), each registering concrete array types for the backend hooks (<code>to_sparse_csc</code> / <code>to_sparse_csr</code> / <code>to_dense_matrix</code>, which are identity on CPU) and precompiling the kernels for the GPU array types. Loading the extension happens through <code>@using_gpu()</code> or an explicit <code>using CUDA</code>; <code>set_backend(&quot;cuda&quot;)</code> only makes sense afterwards.</p><h2 id="Data-layout-conventions" tabindex="-1">Data layout conventions <a class="header-anchor" href="#Data-layout-conventions" aria-label="Permalink to &quot;Data layout conventions {#Data-layout-conventions}&quot;">​</a></h2><ul><li><p>spin/field arrays: flat <code>3N</code>, interleaved per cell (see above);</p></li><li><p>scalar parameters: <code>Fill{T,1}</code> or <code>Vector{T}</code> of length N (never scalars);</p></li><li><p><code>mesh.region</code>: per-cell region id (<code>Int</code>), set with <code>set_region</code>, consumed by <code>region_map</code> and the stencil partition layer;</p></li><li><p>energies saved per term via <code>SaverItem</code>s appended to <code>sim.saver.items</code>.</p></li></ul>',16))])}const _=d(p,[["render",h]]);export{v as __pageData,_ as default};
